import { NextResponse } from 'next/server';
import { auth } from '@clerk/nextjs';

// Special route handler for sign-in page
export async function GET(request) {
  console.log('Sign-in root route handler activated');

  // Get the URL from the request
  const url = new URL(request.url);

  // Get the redirect_url parameter
  const redirectUrl = url.searchParams.get('redirect_url');

  // Check if the user is already authenticated
  const { userId } = await auth();
  const isAuthenticated = !!userId;

  // If user is authenticated and there's a redirect_url parameter, redirect to it
  if (isAuthenticated && redirectUrl) {
    console.log('User is authenticated, redirecting to', redirectUrl);
    
    // If the redirect URL includes http, check if it's to our own domain
    if (redirectUrl.includes('http')) {
      try {
        const currentDomain = process.env.NEXT_PUBLIC_URL || 'http://localhost:3001';
        const redirectUrlObj = new URL(redirectUrl);
        const currentDomainObj = new URL(currentDomain);
        
        // If the redirect URL is to our own domain, extract the path and redirect to it
        if (redirectUrlObj.hostname === currentDomainObj.hostname) {
          console.log('Redirecting to internal path:', redirectUrlObj.pathname);
          const internalUrl = new URL(redirectUrlObj.pathname + redirectUrlObj.search + redirectUrlObj.hash, currentDomain);
          return NextResponse.redirect(internalUrl, { status: 307 });
        } else {
          // External domain - fallback to dashboard
          console.warn('Attempted redirect to external domain, falling back to dashboard');
          const dashboardUrl = new URL('/dashboard', currentDomain);
          return NextResponse.redirect(dashboardUrl, { status: 307 });
        }
      } catch (error) {
        console.error('Error parsing redirect URL:', error);
        const dashboardUrl = new URL('/dashboard', process.env.NEXT_PUBLIC_URL || 'http://localhost:3001');
        return NextResponse.redirect(dashboardUrl, { status: 307 });
      }
    }
    
    // If the redirect URL starts with /, use it
    if (redirectUrl.startsWith('/')) {
      console.log('Redirecting to', redirectUrl);
      const targetUrl = new URL(redirectUrl, process.env.NEXT_PUBLIC_URL || 'http://localhost:3001');
      return NextResponse.redirect(targetUrl, { status: 307 });
    }
  }

  // If we're on the sign-in page without a redirect URL or the user is not authenticated,
  // let the page handle it
  console.log('No redirect URL or user not authenticated, letting the page handle it');
  return NextResponse.next();
}
